import Foundation

/// Java results are regenerated by ChainToolOracle.py from the frozen bundle.
#if !COMBINED_BOARD_CHECKS
  @main
#endif
enum ChainToolChecks {
  static func require(_ value: @autoclosure () -> Bool, _ name: String) {
    if !value() { fatalError(name) }
  }

  static let geometry = BoardGeometry(bounds: CGRect(x: 0, y: 0, width: 830, height: 830))

  static func path(_ atoms: [[Int]], _ strong: [Bool], closed: Bool = false) -> ChainToolPath {
    ChainToolPath(
      nodes: atoms.map { ChainToolNode(atoms: $0, color: 0) },
      edges: strong.map { ChainToolEdge(strong: $0, color: 0) }, closed: closed)
  }

  static func string(_ path: ChainToolPath) -> String {
    path.nodes.map { $0.atoms.map(String.init).joined(separator: "+") }.joined(separator: "/") + ":"
      + path.edges.map { $0.strong ? "s" : "w" }.joined()
  }

  static func main() throws {
    let fixture = try String(contentsOfFile: CommandLine.arguments[1], encoding: .utf8)
    let rows = fixture.split(separator: "\n").map {
      $0.split(separator: "\t", omittingEmptySubsequences: false).map(String.init)
    }
    var cases = 0
    for row in rows where row[0] == "S" {
      let p = row[1].split(separator: ",").map { CGFloat(Int($0)!) }
      var state = BoxToolState()
      state.edit(
        start: CGPoint(x: p[0], y: p[1]), end: CGPoint(x: p[2], y: p[3]),
        dragged: true, erase: false, group: 2, deleteGroup: nil, geometry: geometry)
      require(
        state.footprint == Set(row[2].split(separator: ",").map { Int($0)! }),
        row.joined(separator: " "))
      cases += 1
    }
    let open = path([[1, 2, 3], [11], [21], [31], [41]], [true, false, true, false])
    let cycle = path([[1], [11], [21], [31]], [true, false, true, false], closed: true)
    for row in rows where row[0] == "L" {
      let actual: String
      switch row[1] {
      case "cut-open", "cut-loop":
        let original = row[1] == "cut-loop" ? cycle : open
        actual = original.cut(edges: [1], members: [:], deleteGroup: nil).map(string).joined(
          separator: "|")
      case "trim-group":
        actual = string(open.cut(edges: [], members: [0: [1, 2]], deleteGroup: nil)[0])
      case "disconnected", "branch":
        let extra =
          row[1] == "branch" ? path([[21], [809]], [true]) : path([[801], [809]], [true])
        var state = ChainToolState()
        state.paths = [open, extra]
        actual = state.assembly().problem
      default:
        var state = ChainToolState()
        state.paths = [path([[1], [11]], [true]), path([[21], [11]], [false])]
        actual = state.assembled().map(string) ?? "missing"
      }
      require(actual == row[2], "\(row[1]): \(actual) != \(row[2])")
      cases += 1
    }
    for row in rows where row[0] == "R" {
      let fields = row[4].split(separator: ":")
      let nodes = fields[0].split(separator: "/").map { n in
        n.split(separator: "+").map { Int($0)! }
      }
      let chain = path(nodes, fields[1].map { $0 == "s" }, closed: row[5] == "true")
      var board = NativeBoardSnapshot(
        values: Array(repeating: 0, count: 81), fixed: Array(repeating: false, count: 81),
        candidates: Array(repeating: 511, count: 81), userCandidates: Array(repeating: 0, count: 81)
      )
      for a in row[6].split(separator: ",").map({ Int($0)! }) {
        board.candidates[a / 10] &= ~NativeBoardSnapshot.bit(UInt8(a % 10))
      }
      let result = try chain.analyze(board: board)
      require(result.status.rawValue == row[2], "\(row[1]) status \(result.status.rawValue)")
      let conclusion: String
      if let cell = result.step?.placementCell, let digit = result.step?.placementDigit {
        conclusion = "+\(cell * 10 + Int(digit))"
      } else if let step = result.step {
        let atoms: [Int] = (0..<81).flatMap { cell -> [Int] in
          (1...9).filter { step.deletions[cell] & NativeBoardSnapshot.bit(UInt8($0)) != 0 }
            .map { cell * 10 + $0 }
        }
        conclusion = atoms.map(String.init).joined(separator: ",")
      } else {
        conclusion = "-"
      }
      require(conclusion == row[3], "\(row[1]) conclusion \(conclusion)")
      require(result.step == nil || !result.stages.isEmpty, "missing proof for \(row[1])")
      cases += 1
    }
    try previewCases(rows: rows)
    drawingGeometry()
    cases += rows.filter { ["P", "I"].contains($0[0]) }.count
    var box = BoxToolState()
    let center = CGPoint(x: geometry.rect(40).midX, y: geometry.rect(40).midY)
    for group in [0, 2, 2] {
      box.edit(
        start: center, end: center, dragged: false, erase: false, group: group, deleteGroup: nil,
        geometry: geometry)
    }
    require(box.groups[0] == [40] && box.groups[2] == [40], "overlapping S groups")
    box.edit(
      start: center, end: center, dragged: false, erase: true, group: 0, deleteGroup: 2,
      geometry: geometry)
    require(box.groups[0] == [40] && box.groups[2].isEmpty, "scoped S erase")
    try box.validate()
    var state = ChainToolState()
    state.paths = [cycle]
    state.backtrack(deleteGroup: nil)
    require(
      state.paths[0].edges.count == 3 && state.paths[0].nodes.count == 4 && !state.paths[0].closed,
      "cycle backtrack")
    state.backtrack(deleteGroup: nil)
    require(state.paths[0].edges.count == 2 && state.paths[0].nodes.count == 3, "tail backtrack")
    try state.validate()
    require(tryJSON(state) == state, "L persistence")
    print(
      "L/S matched \(cases) Java cases; scoped erase, overlap, backtracking and native persistence passed"
    )
  }

  static func drawingGeometry() {
    for size in [340, 830, 1700] {
      let g = BoardGeometry(bounds: CGRect(x: 0, y: 0, width: size, height: size))
      func clearance(_ samples: [CGPoint], from center: CGPoint) -> CGFloat {
        samples.map { hypot($0.x - center.x, $0.y - center.y) }.min()!
      }
      func checkEndpoints(_ route: ChainToolRoute, _ a: Int, _ b: Int) {
        let points = route.samples(count: 48)
        for atom in [a, b] {
          require(clearance(points, from: ChainToolNode.point(atom, g)) >= g.unit * 0.214,
                  "edge must clear the candidate ring and active cue")
        }
      }
      let near = path([[402], [405]], [false])
      let reverse = path([[405], [402]], [true])
      let lanes = ChainToolState(paths: [near, reverse]).routes(g, board: nil)
      let weak = lanes[0][0]!, strong = lanes[1][0]!
      checkEndpoints(weak, 402, 405)
      checkEndpoints(strong, 405, 402)
      require(hypot(weak.point(0.5).x - strong.point(0.5).x, weak.point(0.5).y - strong.point(0.5).y) > g.unit * 0.15,
              "opposite arrows between adjacent candidates must use separate lanes")
      let crossing = path([[715], [253]], [true])
      let withRing = ChainToolState(paths: [crossing, path([[712]], [])]).routes(g, board: nil)[0][0]!
      require(clearance(withRing.samples(count: 120), from: ChainToolNode.point(712, g)) > g.unit * 0.20,
              "long edge must avoid the neighboring ring at its origin")
      var board = NativeBoardSnapshot(
        values: Array(repeating: 0, count: 81), fixed: Array(repeating: false, count: 81),
        candidates: Array(repeating: 511, count: 81), userCandidates: Array(repeating: 0, count: 81))
      let betweenSlots = ChainToolState(paths: [path([[565], [652]], [true])]).routes(g, board: board)[0][0]!
      let gap = betweenSlots.samples(count: 48)
      for atom in [567, 568, 569] {
        require(clearance(gap, from: ChainToolNode.point(atom, g)) > g.unit * 0.115,
                "edge has a visible route between tightly spaced digits")
      }
      board.values[41] = 3
      board.candidates[41] = 0
      let viaValue = ChainToolState(paths: [path([[329], [501]], [true])]).routes(g, board: board)[0][0]!
      let rect = g.rect(41)
      require(clearance(viaValue.samples(count: 90), from: CGPoint(x: rect.midX, y: rect.midY)) > g.unit * 0.29,
              "route must bend around a filled digit")
    }
    let loop = path([[1], [11], [21], [31]], [true, false, false, true], closed: true)
    var separate = path([[71], [81], [91]], [false, false])
    separate.edges[0].color = 2
    separate.edges[1].color = 2
    let state = ChainToolState(paths: [loop, separate], active: 0)
    require(state.junctionCounts() == ChainJunctionCounts(strong: 1, weak: 2),
            "all chains include the loop seam and disconnected paths")
    require(state.junctionCounts(group: 0) == ChainJunctionCounts(strong: 1, weak: 1) &&
            state.junctionCounts(group: 2) == ChainJunctionCounts(weak: 1) &&
            state.junctionCounts(group: 3) == ChainJunctionCounts(), "counts follow the selected edge color, not node color")
    var second = path([[11], [21]], [true])
    let first = path([[1], [11]], [true])
    let reversed = path([[11], [1]], [true])
    require(ChainToolState(paths: [first, second, reversed]).junctionCounts(group: 0) == ChainJunctionCounts(strong: 1),
            "joining segments counts one junction; reverse duplicates do not add branches")
    second.edges[0].color = 2
    let mixed = ChainToolState(paths: [first, second])
    require(mixed.junctionCounts().strong == 1 && mixed.junctionCounts(group: 0).strong == 0 &&
            mixed.junctionCounts(group: 2).strong == 0, "mixed-color joins count only in the all-chains column")
    let conflict = ChainToolState(paths: [path([[1], [11]], [true]), path([[11], [1]], [false])])
    require(conflict.junctionCounts() == ChainJunctionCounts(hasAmbiguousNodes: true),
            "conflicting strokes cannot produce a junction count")
    let branch = ChainToolState(paths: [first, second, path([[11], [31]], [true]), separate])
    require(branch.junctionCounts() == ChainJunctionCounts(weak: 1, hasAmbiguousNodes: true),
            "an ambiguous node does not hide an independent valid junction")
  }

  static func previewCases(rows: [[String]]) throws {
    var board = NativeBoardSnapshot(
      values: Array(repeating: 0, count: 81), fixed: Array(repeating: false, count: 81),
      candidates: Array(repeating: 511, count: 81), userCandidates: Array(repeating: 0, count: 81))
    func mark(_ atom: Int, _ group: Int, _ circle: Bool, _ start: Bool) -> InkStroke {
      InkStroke(
        kind: circle ? .circle : .cross, group: group, width: 0.004, cell: atom / 10,
        digit: atom % 10, start: start)
    }
    var ink = InkToolState()
    var boxes = BoxToolState()
    func expect(_ label: String, _ source: [Int], _ target: [Int]) {
      var state = ChainToolState()
      state.paths = [path([source], [])]
      state.active = 0
      let relations = state.previewRelations(board: board, boxes: boxes, ink: ink)
      let actual = relations.first { $0.key.atoms == target }?.value ?? 0
      let row = rows.first { $0[0] == "P" && $0[1] == label }!
      require(String(actual) == row[2], "\(label) expected \(row[2]) got \(actual)")
    }
    ink.strokes = [
      mark(1, 0, false, true), mark(11, 0, false, true), mark(403, 0, true, false),
      mark(202, 1, true, true), mark(775, 1, false, false),
    ]
    expect("complete-cross-start", [1, 11], [403])
    expect("partial-cross-start", [1], [403])
    expect("circle-to-distant-cross", [202], [775])
    ink.strokes = [
      mark(1, 0, true, true), mark(11, 0, true, true), mark(403, 1, true, true),
      mark(1, 1, false, false), mark(606, 2, true, true), mark(11, 2, false, false),
    ]
    expect("whole-circle-residual", [1], [11])
    expect("third-source-exclusion", [403], [606])
    boxes.groups[0] = [0, 1]
    board.candidates[0] = 3
    board.candidates[1] = 9
    expect("als-whole-digit", [14], [1, 11])
    expect("als-other-digit", [14], [2])
    expect("als-partial", [1], [14])
    // Two distinct P sources expose two overlapping OR targets. The chosen
    // group must still be available when the user confirms the picker.
    let simpleBoard = NativeBoardSnapshot(
      values: Array(repeating: 0, count: 81), fixed: Array(repeating: false, count: 81),
      candidates: Array(repeating: 511, count: 81), userCandidates: Array(repeating: 0, count: 81))
    var pickerInk = InkToolState()
    pickerInk.strokes =
      [1, 11, 21].map { mark($0, 0, true, true) } + [1, 11, 31].map { mark($0, 1, true, true) }
    var drawing = ChainToolState()
    drawing.append(ChainToolNode(atoms: [1], color: 0), group: 0)
    let p = BoardPress(
      at: 10, point: ChainToolNode.point(11, geometry), button: .left, modifiers: [], cell: 1,
      digit: 1)
    var session = ChainToolSession()
    session.click(
      p, twice: false, preciseEligible: false, palette: 0, deleteGroup: nil, preview: true,
      board: simpleBoard, state: &drawing, ink: pickerInk)
    require(session.choices.count == 2, "overlapping P-derived OR picker")
    let choice = session.choices[0]
    let before = drawing
    var lostPremises = session
    lostPremises.choose(choice, board: simpleBoard, state: &drawing, preview: true, ink: .init())
    require(drawing == before, "stale P basis added a chain endpoint")
    var released = session
    released.cancelPreviewChoice()
    require(released.choices.isEmpty, "released preview kept a picker")
    session.choose(choice, board: simpleBoard, state: &drawing, preview: true, ink: pickerInk)
    require(
      drawing.paths[0].nodes.last?.atoms == choice.atoms, "confirmed exact OR selection dropped")
    var composite = AnnotationOverlay.Composite()
    for item in [mark(405, 3, true, true), mark(405, 0, true, false), mark(405, 3, true, false)] {
      composite.add(AnnotationOverlay.Source(mark: item, ghost: false))
    }
    let order = composite.ordered.map { String($0.mark.group) }.joined(separator: ",")
    let roles = composite.byRole.keys.sorted().map(String.init).joined(separator: ",")
    require(rows.first { $0[1] == "group-source-order" }?[2] == order, "Java source order")
    require(rows.first { $0[1] == "source-roles" }?[2] == roles, "Java source roles")
  }

  static func tryJSON(_ state: ChainToolState) -> ChainToolState? {
    try? JSONDecoder().decode(ChainToolState.self, from: JSONEncoder().encode(state))
  }
}
